import{_ as t,o as i,c as a,a0 as s}from"./chunks/framework.CShDTZbC.js";const u=JSON.parse('{"title":"DevFix Demo Script","description":"","frontmatter":{},"headers":[],"relativePath":"demo-script.md","filePath":"demo-script.md"}'),o={name:"demo-script.md"};function r(n,e,c,l,h,d){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="devfix-demo-script" tabindex="-1">DevFix Demo Script <a class="header-anchor" href="#devfix-demo-script" aria-label="Permalink to &quot;DevFix Demo Script&quot;">​</a></h1><p>This script is designed for a 3-5 minute live presentation of DevFix for hackathon judging.</p><h2 id="_0-00–0-30-—-problem" tabindex="-1">0:00–0:30 — Problem <a class="header-anchor" href="#_0-00–0-30-—-problem" aria-label="Permalink to &quot;0:00–0:30 — Problem&quot;">​</a></h2><p><strong>Speaker:</strong></p><blockquote><p>&quot;Local development failures are incredibly common and almost always environment-specific. When developers run into these issues, they often turn to LLM coding agents. But LLMs only <em>suggest</em> fixes—they don&#39;t prove they work, which often leads to time wasted on hallucinations.&quot;</p></blockquote><h2 id="_0-30–1-00-—-architecture" tabindex="-1">0:30–1:00 — Architecture <a class="header-anchor" href="#_0-30–1-00-—-architecture" aria-label="Permalink to &quot;0:30–1:00 — Architecture&quot;">​</a></h2><p><strong>Speaker:</strong></p><blockquote><p>&quot;DevFix solves this by replacing blind suggestions with <strong>Verified Autonomous Recovery</strong>. The agent investigates the broken codebase, applies repairs using structured tools inside a secure, isolated Docker sandbox. The critical piece is the <strong>Deterministic Verifier</strong>—the LLM has no authority to say &#39;I fixed it&#39;. It has to mathematically prove to the verifier that the environment boots successfully before it stops.&quot;</p></blockquote><p><em>(Show <code>docs/architecture.md</code> diagram briefly if applicable)</em></p><h2 id="_1-00–2-30-—-live-dev-04-missing-native-dependency" tabindex="-1">1:00–2:30 — Live DEV-04 (Missing Native Dependency) <a class="header-anchor" href="#_1-00–2-30-—-live-dev-04-missing-native-dependency" aria-label="Permalink to &quot;1:00–2:30 — Live DEV-04 (Missing Native Dependency)&quot;">​</a></h2><p><strong>Speaker:</strong></p><blockquote><p>&quot;Let&#39;s run a live demo. We&#39;ll use benchmark case <code>DEV-04</code>, where a Node.js project fails to build because it relies on a native dependency that requires Python, which isn&#39;t installed.&quot;</p></blockquote><p><strong>Action:</strong> Run the command in terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/devfix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DEV-04</span></span></code></pre></div><p><strong>Speaker:</strong></p><blockquote><p>&quot;Watch the output. The agent investigates the Dockerfile and <code>package.json</code>. It realizes the build script relies on <code>node-gyp</code>. It patches the dependencies, runs the build, and then the external Verifier takes over. The Verifier runs the script, confirms a 0 exit code, and explicitly flags the repair as successful.&quot;</p></blockquote><p><em>(Wait for the command to finish and show the ✓ Repair successful screen)</em></p><h2 id="_2-30–3-30-—-live-dev-05-cascading-failure" tabindex="-1">2:30–3:30 — Live DEV-05 (Cascading Failure) <a class="header-anchor" href="#_2-30–3-30-—-live-dev-05-cascading-failure" aria-label="Permalink to &quot;2:30–3:30 — Live DEV-05 (Cascading Failure)&quot;">​</a></h2><p><strong>Speaker:</strong></p><blockquote><p>&quot;Now let&#39;s look at <code>DEV-05</code>, a multi-step cascading failure. Here, we are missing the <code>typescript</code> compiler entirely, and once that&#39;s fixed, we will hit a strict-mode compilation type error in the code.&quot;</p></blockquote><p><strong>Action:</strong> Run the command in terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin/devfix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> demo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DEV-05</span></span></code></pre></div><p><strong>Speaker:</strong></p><blockquote><p>&quot;Notice how DevFix handles this iterative process. It will first install typescript, but when it attempts to start the server again, the Deterministic Verifier blocks it and kicks it back with the exact compilation error. DevFix reads the error, patches the code, and passes the verifier on the second try.&quot;</p></blockquote><p><em>(Wait for the command to finish)</em></p><h2 id="_3-30–4-00-—-evidence-benchmarks" tabindex="-1">3:30–4:00 — Evidence &amp; Benchmarks <a class="header-anchor" href="#_3-30–4-00-—-evidence-benchmarks" aria-label="Permalink to &quot;3:30–4:00 — Evidence &amp; Benchmarks&quot;">​</a></h2><p><strong>Speaker:</strong></p><blockquote><p>&quot;We&#39;ve run this system against a rigorous benchmark of 5 diverse local development failure profiles. We achieved a <strong>60% verified recovery rate (3/5)</strong>. Crucially, the 2 failures hit the iteration limits—our deterministic verifier perfectly protected the system from claiming false successes.&quot;</p></blockquote><p><strong>Action:</strong> Briefly show <code>artifacts/example-run.json</code> to highlight the scrubbed, perfectly structured telemetry that records the tool executions.</p><h2 id="final-message" tabindex="-1">Final Message <a class="header-anchor" href="#final-message" aria-label="Permalink to &quot;Final Message&quot;">​</a></h2><p><strong>Speaker:</strong></p><blockquote><p>&quot;The key idea isn&#39;t that the LLM always gets the answer right on the first try. The key idea is that DevFix creates a controlled environment where the agent can investigate, act, and then has to <em>prove</em> that its repair actually worked.&quot;</p></blockquote>',32)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
